// @ts-nocheck
// EnT-DB "submit" edge function (Supabase / Deno).
// Receives a form submission, recomputes the score on the server, stores the entry
// as "pending" and notifies the curator. GENERATED by tools/build-function.mjs from
// tools/function-template.ts and docs/assets/score.js: edit those, not this file.
//
// Secrets (Supabase dashboard -> Edge Functions -> Secrets). All optional except SITE_URL:
//   SITE_URL        public address of the site, e.g. https://nuniwo-source.github.io/EnT-DB
//   RESEND_API_KEY  Resend API key; with NOTIFY_EMAIL, sends an email per submission
//   NOTIFY_EMAIL    where to send it; comma-separated for several curators
//   NOTIFY_FROM     sender, default "EnT-DB <onboarding@resend.dev>"
//   NTFY_TOPIC      ntfy.sh topic name; sends a phone push per submission
//   IP_SALT         any random string; salts the hash used for rate limiting
//   SERVICE_KEY     only if the built-in SUPABASE_SERVICE_ROLE_KEY is missing: a secret (sb_secret_...) key
// Deploy with "Verify JWT" switched OFF: visitors are anonymous and send only the publishable key.

// ---- begin docs/assets/score.js ----
/* EnT-DB scoring and normalisation.
 * One file, two homes: the browser loads it for the live preview, and the
 * same text is embedded in supabase/functions/submit/index.ts, where the
 * score that counts is computed. Edit here, then run tools/build-function.mjs. */
(function (root) {
  "use strict";

  var KCAL_PER_EV = 23.0605, KJ_PER_KCAL = 4.184;

  function str(v, max) { return String(v == null ? "" : v).trim().slice(0, max || 500); }
  function num(v) { var n = parseFloat(v); return isFinite(n) ? n : NaN; }
  function pick(v, allowed, fallback) { return allowed.indexOf(v) >= 0 ? v : fallback; }

  /* Raw form payload -> clean, length-capped fields. */
  function normalize(p) {
    p = p || {};
    var unit = pick(p.unit, ["kcal", "kj", "ev"], "kcal");
    var k = unit === "kj" ? 1 / KJ_PER_KCAL : unit === "ev" ? KCAL_PER_EV : 1;
    var et = num(p.et), unc = num(p.unc);
    var doi = str(p.doi, 200).replace(/^https?:\/\/(dx\.)?doi\.org\//i, "").replace(/^doi:\s*/i, "");
    return {
      name: str(p.name, 200), cls: str(p.cls, 80), smiles: str(p.smiles, 400),
      role: pick(p.role, ["acceptor", "donor", "both"], "acceptor"),
      et: et, unit: unit, unc: unc,
      kcal: isNaN(et) ? NaN : et * k,
      uncKcal: isNaN(unc) ? NaN : Math.abs(unc) * k,
      origin: p.origin === "calc" ? "calc" : "exp",
      kind: str(p.kind, 80), tech: str(p.tech, 80), solvent: str(p.solvent, 120), temp: str(p.temp, 60),
      func: str(p.func, 120), basis: str(p.basis, 120), solv: str(p.solv, 120),
      cite: str(p.cite, 400), doi: doi, loc: str(p.loc, 200), quote: str(p.quote, 300),
      uv: str(p.uv, 200), direct: str(p.direct, 200), by: str(p.by, 120)
    };
  }

  function gradeOf(n) {
    return n >= 80 ? { label: "Good", cls: "exp" } : n >= 50 ? { label: "Fair", cls: "warn" } : { label: "Poor", cls: "bad" };
  }

  /* ctx.structureOk : true | false | null (null = could not be checked)
   * ctx.doiResolves : true | false | null (null = not checked yet)
   * ctx.same        : entries with the same structure [{name, doi, et_kcal}], or null if unknown */
  function scoreEntry(f, ctx) {
    ctx = ctx || {};
    var items = [];
    function add(label, got, max, note) { items.push({ label: label, got: got, max: max, note: note || "" }); }

    if (ctx.structureOk == null) add("Structure parses", 0, 15, "Not checked: the structure library was unavailable");
    else add("Structure parses", ctx.structureOk ? 15 : 0, 15, ctx.structureOk ? "" : (f.smiles ? "The SMILES could not be read" : "No structure given"));

    add("Name given", f.name ? 3 : 0, 3);

    var okEt = !isNaN(f.kcal) && f.kcal >= 20 && f.kcal <= 120;
    add("E_T in a plausible range", okEt ? 12 : 0, 12, isNaN(f.kcal) ? "No value given" : okEt ? "" : "Outside 20–120 kcal/mol: check the unit");

    add("Value type stated", f.kind && f.kind !== "Other or not stated" ? 8 : 0, 8);

    if (f.origin === "calc") {
      add("Method or functional", f.func ? 8 : 0, 8);
      add("Basis set", f.basis ? 7 : 0, 7);
      add("Solvent model", f.solv ? 5 : 0, 5);
      var ck = /^Computed/.test(f.kind);
      add("Value type matches a computation", ck ? 3 : 0, 3, ck ? "" : "Choose adiabatic or vertical");
    } else {
      add("Technique", f.tech ? 10 : 0, 10);
      add("Solvent or matrix", f.solvent ? 5 : 0, 5);
      add("Temperature", f.temp ? 5 : 0, 5);
      add("Uncertainty given", !isNaN(f.unc) ? 3 : 0, 3);
    }

    var doiOk = /^10\.\d{4,9}\/\S+$/.test(f.doi);
    add("DOI well formed", doiOk ? 6 : 0, 6, f.doi && !doiOk ? "This does not look like a DOI" : "");
    if (!doiOk) add("DOI resolves", 0, 6, f.doi ? "" : "No DOI given");
    else if (ctx.doiResolves == null) add("DOI resolves", 0, 6, "Checked when the entry is submitted");
    else add("DOI resolves", ctx.doiResolves ? 6 : 0, 6, ctx.doiResolves ? "" : "doi.org does not know this DOI");

    add("Citation", f.cite ? 5 : 0, 5);
    add("Location in the paper", f.loc ? 6 : 0, 6);

    var words = f.quote ? f.quote.split(/\s+/).length : 0;
    add("Verbatim line", words > 0 && words <= 25 ? 4 : 0, 4, words > 25 ? "Keep it to one short line (25 words or fewer)" : "");

    var cons = 0, note = "No structure to compare";
    if (ctx.same && !isNaN(f.kcal)) {
      var dup = null, best = Infinity;
      ctx.same.forEach(function (d) {
        var diff = Math.abs(Number(d.et_kcal) - f.kcal);
        if (diff < best) best = diff;
        if (f.doi && String(d.doi || "").toLowerCase() === f.doi.toLowerCase() && diff < 0.05) dup = d;
      });
      if (dup) { cons = 0; note = "Looks like a duplicate of “" + dup.name + "” (same structure, DOI and value)"; }
      else if (!ctx.same.length) { cons = 8; note = "No existing entry for this structure"; }
      else {
        cons = best <= 5 ? 8 : best <= 10 ? 5 : 2;
        note = best <= 5 ? "Within 5 kcal/mol of an existing entry for this structure"
          : "Differs by " + best.toFixed(1) + " kcal/mol from the closest existing entry. This can be right if the value type differs";
      }
    }
    add("Consistency with the database", cons, 8, note);

    add("UV-vis or excitation data", f.uv || f.direct ? 4 : 0, 4);

    var total = items.reduce(function (a, i) { return a + i.got; }, 0);
    return { total: total, grade: gradeOf(total).label, items: items };
  }

  /* The minimum a submission needs. Returns a message, or null when it can be sent. */
  function requiredError(f, ctx) {
    ctx = ctx || {};
    if (!f.smiles) return "Add the structure as a SMILES or draw it.";
    if (ctx.structureOk === false) return "The SMILES could not be read. Fix it or redraw the structure.";
    if (isNaN(f.kcal)) return "Enter the triplet energy value.";
    if (!f.cite && !f.doi) return "Add a citation or a DOI so the value can be traced.";
    return null;
  }

  /* Normalised fields + score -> database row (without status, ids or server-only columns). */
  function toDoc(f, sc) {
    var unitLabel = f.unit === "kj" ? "kJ/mol" : f.unit === "ev" ? "eV" : "kcal/mol";
    var doc = {
      name: f.name || "(unnamed)", smiles: f.smiles, role: f.role, origin: f.origin,
      et_kcal: Math.round(f.kcal * 10) / 10,
      et_reported: f.et + (isNaN(f.unc) ? "" : " ± " + f.unc) + " " + unitLabel,
      et_type: f.kind || "Not stated",
      method: f.origin === "calc" ? ["Computation", f.func, f.basis].filter(Boolean).join(", ") : (f.tech || "Not stated"),
      conditions: f.origin === "calc" ? f.solv : [f.solvent, f.temp].filter(Boolean).join(", "),
      source_kind: "form", score: sc.total, score_items: sc.items
    };
    if (!isNaN(f.uncKcal)) doc.et_unc = Math.round(f.uncKcal * 10) / 10;
    [["cls", f.cls], ["citation", f.cite], ["doi", f.doi], ["location", f.loc], ["quote", f.quote],
     ["uv", f.uv], ["direct_exc", f.direct], ["submitted_by", f.by]].forEach(function (p) { if (p[1]) doc[p[0]] = p[1]; });
    return doc;
  }

  root.EntScore = { normalize: normalize, gradeOf: gradeOf, scoreEntry: scoreEntry, requiredError: requiredError, toDoc: toDoc };
})(typeof globalThis !== "undefined" ? globalThis : this);
// ---- end docs/assets/score.js ----

const EntScore = globalThis.EntScore;
const SB_URL = Deno.env.get("SUPABASE_URL");
const SB_KEY = Deno.env.get("SERVICE_KEY") || Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
const MAX_PER_HOUR = 5;

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
function json(body, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...CORS, "Content-Type": "application/json" } });
}
function rest(path, init = {}) {
  return fetch(`${SB_URL}/rest/v1/${path}`, {
    ...init,
    // "sb_secret_..." keys go in apikey only; a legacy service-role JWT is also sent as Bearer.
    headers: {
      apikey: SB_KEY, "Content-Type": "application/json",
      ...(SB_KEY.startsWith("sb_") ? {} : { Authorization: `Bearer ${SB_KEY}` }),
      ...(init.headers || {}),
    },
  });
}
async function sha256(text) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function esc(s) {
  return String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}

// OpenChemLib is loaded lazily; if it cannot be loaded the structure is simply "not checked".
let oclCache;
async function loadOCL() {
  if (oclCache !== undefined) return oclCache;
  try {
    const m = await import("npm:openchemlib@8.19.0");
    oclCache = m?.default?.Molecule ? m.default : m?.Molecule ? m : null;
  } catch (_e) {
    oclCache = null;
  }
  return oclCache;
}
// -> { ok: true|false|null, idcode: string|null }
async function checkStructure(smiles) {
  const OCL = await loadOCL();
  if (!OCL) return { ok: null, idcode: null };
  try {
    const mol = OCL.Molecule.fromSmiles(smiles);
    if (!(mol.getAllAtoms() > 0)) return { ok: false, idcode: null };
    return { ok: true, idcode: mol.getIDCode() };
  } catch (_e) {
    return { ok: false, idcode: null };
  }
}
// -> true | false | null (null when doi.org could not be asked)
async function doiResolves(doi) {
  if (!/^10\.\d{4,9}\/\S+$/.test(doi)) return null;
  try {
    const r = await fetch(`https://doi.org/api/handles/${encodeURIComponent(doi)}`, { signal: AbortSignal.timeout(5000) });
    if (r.status === 404) return false;
    if (!r.ok) return null;
    const body = await r.json();
    return body?.responseCode === 1;
  } catch (_e) {
    return null;
  }
}

async function notify(row) {
  const site = (Deno.env.get("SITE_URL") || "").replace(/\/+$/, "");
  const reviewUrl = site ? `${site}/admin.html` : "";
  const grade = EntScore.gradeOf(row.score).label;
  const subject = `EnT-DB: new submission, ${row.name} (${row.score}/100, ${grade})`;
  const lines = [
    ["Molecule", row.name], ["SMILES", row.smiles], ["E_T", `${row.et_kcal} kcal/mol (reported: ${row.et_reported})`],
    ["Value type", row.et_type], ["Method", row.method], ["Conditions", row.conditions],
    ["Source", row.citation], ["DOI", row.doi], ["Where", row.location], ["Submitted by", row.submitted_by],
  ].filter((l) => l[1]);
  const lost = (row.score_items || []).filter((i) => i.got < i.max).map((i) => `${i.label} (${i.got}/${i.max})`);
  const jobs = [];

  const key = Deno.env.get("RESEND_API_KEY"), to = (Deno.env.get("NOTIFY_EMAIL") || "").split(",").map((s) => s.trim()).filter(Boolean);
  if (key && to.length) {
    const html = `<h2 style="font-family:sans-serif">New submission: ${esc(row.name)}</h2>
<p style="font-family:sans-serif"><b>Score ${row.score}/100 (${grade})</b>${lost.length ? "<br>Points lost on: " + esc(lost.join("; ")) : ""}</p>
<table style="font-family:sans-serif;border-collapse:collapse">${lines.map((l) => `<tr><td style="padding:2px 12px 2px 0;color:#666">${esc(l[0])}</td><td>${esc(l[1])}</td></tr>`).join("")}</table>
${reviewUrl ? `<p style="font-family:sans-serif"><a href="${esc(reviewUrl)}">Open the review queue</a> to approve or reject it.</p>` : ""}`;
    jobs.push(fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from: Deno.env.get("NOTIFY_FROM") || "EnT-DB <onboarding@resend.dev>", to, subject, html }),
      signal: AbortSignal.timeout(8000),
    }).then((r) => { if (!r.ok) console.error("resend failed", r.status); }));
  }

  const topic = Deno.env.get("NTFY_TOPIC");
  if (topic) {
    const headers = { Title: "EnT-DB: new submission", Tags: "test_tube" };
    if (reviewUrl) headers.Click = reviewUrl;
    jobs.push(fetch(`https://ntfy.sh/${encodeURIComponent(topic)}`, {
      method: "POST", headers,
      body: `${row.name}: ${row.et_kcal} kcal/mol, score ${row.score}/100 (${grade})`,
      signal: AbortSignal.timeout(8000),
    }).then((r) => { if (!r.ok) console.error("ntfy failed", r.status); }));
  }
  await Promise.allSettled(jobs);   // a failed notification never fails the submission
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return json({ error: "Use POST." }, 405);
  if (!SB_URL || !SB_KEY) return json({ error: "The server is not configured." }, 500);

  let payload;
  try {
    const text = await req.text();
    if (text.length > 20000) return json({ error: "The submission is too large." }, 400);
    payload = JSON.parse(text);
  } catch (_e) {
    return json({ error: "The submission could not be read." }, 400);
  }
  if (!payload || typeof payload !== "object") return json({ error: "The submission could not be read." }, 400);

  // Honeypot: real visitors never see or fill this field. Pretend it worked.
  if (String(payload.website || "").trim()) return json({ id: null, score: 0, grade: "Poor" });

  // Shared site login: enforced by the database, so it cannot be skipped from the browser.
  const acc = await rest("rpc/check_access", {
    method: "POST",
    body: JSON.stringify({ p_user: String(payload.access_user || "").slice(0, 100), p_pass: String(payload.access_pass || "").slice(0, 200) }),
  });
  if (!acc.ok) return json({ error: "The server could not check your access." }, 500);
  if ((await acc.json()) !== true) return json({ error: "Sign in to submit an entry." }, 401);

  const ip = (req.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "unknown";
  const ipHash = await sha256(ip + "|" + (Deno.env.get("IP_SALT") || "ent-db"));
  const since = new Date(Date.now() - 3600 * 1000).toISOString();
  const recent = await rest(`entries?select=id&ip_hash=eq.${ipHash}&created_at=gte.${encodeURIComponent(since)}&limit=${MAX_PER_HOUR}`);
  if (recent.ok && (await recent.json()).length >= MAX_PER_HOUR) return json({ error: "Too many submissions. Try again later." }, 429);

  const f = EntScore.normalize(payload);
  const [structure, resolves] = await Promise.all([checkStructure(f.smiles), doiResolves(f.doi)]);

  let same = null;
  if (structure.ok && structure.idcode) {
    const r = await rest(`entries?select=name,doi,et_kcal&status=neq.rejected&idcode=eq.${encodeURIComponent(structure.idcode)}&limit=50`);
    same = r.ok ? await r.json() : null;
  }
  const ctx = { structureOk: structure.ok, doiResolves: resolves, same };

  const missing = EntScore.requiredError(f, ctx);
  if (missing) return json({ error: missing }, 400);

  const sc = EntScore.scoreEntry(f, ctx);
  const row = { ...EntScore.toDoc(f, sc), status: "pending", idcode: structure.idcode, ip_hash: ipHash };

  const ins = await rest("entries", { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(row) });
  if (!ins.ok) {
    console.error("insert failed", ins.status, await ins.text());
    return json({ error: "The entry could not be stored." }, 500);
  }
  const saved = (await ins.json())[0];

  await notify(saved);
  return json({ id: saved.id, score: sc.total, grade: sc.grade });
});
